package tests

import (
	"context"
	"net/http"
	"sort"
	"testing"

	"exercise/src/dispatch"
)

func byName(spans []dispatch.SpanRecord) map[string]dispatch.SpanRecord {
	m := map[string]dispatch.SpanRecord{}
	for _, s := range spans {
		m[s.Name] = s
	}
	return m
}

func setup() (*dispatch.Service, *dispatch.Tracer, *http.Header) {
	tr := dispatch.NewTracer()
	var got http.Header
	svc := &dispatch.Service{Tracer: tr, Restaurant: func(h http.Header) error { got = h; return nil }}
	return svc, tr, &got
}

func TestIncomingTraceIsContinued(t *testing.T) {
	svc, tr, _ := setup()
	in := http.Header{}
	in.Set(dispatch.HeaderTraceID, "abc")
	in.Set(dispatch.HeaderParentSpan, "remote-1")
	if err := svc.HandleOrder(context.Background(), in, "o-1"); err != nil {
		t.Fatal(err)
	}
	root := byName(tr.Finished())["handle_order"]
	if root.TraceID != "abc" || root.ParentID != "remote-1" {
		t.Fatalf("handle_order should continue the caller's trace: trace=%q parent=%q", root.TraceID, root.ParentID)
	}
}

func TestNewTraceWhenNoHeaders(t *testing.T) {
	svc, tr, _ := setup()
	_ = svc.HandleOrder(context.Background(), http.Header{}, "o-2")
	root := byName(tr.Finished())["handle_order"]
	if root.TraceID == "" || root.ParentID != "" {
		t.Fatalf("expected a fresh root span, got trace=%q parent=%q", root.TraceID, root.ParentID)
	}
}

func TestNestedSpansLinkToParent(t *testing.T) {
	tr := dispatch.NewTracer()
	ctx, a := tr.StartSpan(context.Background(), "a")
	_, b := tr.StartSpan(ctx, "b")
	b.End()
	a.End()
	m := byName(tr.Finished())
	if m["b"].ParentID != m["a"].SpanID || m["b"].TraceID != m["a"].TraceID {
		t.Fatalf("b should be a child of a in the same trace: %+v / %+v", m["b"], m["a"])
	}
}

func TestParallelTasksAreChildrenOfCaller(t *testing.T) {
	svc, tr, _ := setup()
	_ = svc.HandleOrder(context.Background(), http.Header{}, "o-3")
	m := byName(tr.Finished())
	root := m["handle_order"]
	for _, name := range []string{"prepare[0]", "prepare[1]"} {
		if m[name].ParentID != root.SpanID {
			t.Errorf("%s has parent %q, want handle_order span %q", name, m[name].ParentID, root.SpanID)
		}
	}
}

func TestEverySpanSharesOneTrace(t *testing.T) {
	svc, tr, _ := setup()
	_ = svc.HandleOrder(context.Background(), http.Header{}, "o-4")
	spans := tr.Finished()
	sort.Slice(spans, func(i, j int) bool { return spans[i].SpanID < spans[j].SpanID })
	traces := map[string]bool{}
	for _, s := range spans {
		t.Logf("%-14s trace=%-8s span=%-8s parent=%s", s.Name, s.TraceID, s.SpanID, s.ParentID)
		traces[s.TraceID] = true
	}
	if len(spans) != 5 {
		t.Fatalf("expected 5 spans, got %d", len(spans))
	}
	if len(traces) != 1 {
		t.Fatalf("one order should produce one trace, got %d distinct trace IDs", len(traces))
	}
}

func TestLeafSpansHangUnderTheirTask(t *testing.T) {
	svc, tr, _ := setup()
	_ = svc.HandleOrder(context.Background(), http.Header{}, "o-5")
	m := byName(tr.Finished())
	if m["assign_courier"].ParentID != m["prepare[0]"].SpanID {
		t.Fatalf("assign_courier parent = %q, want %q", m["assign_courier"].ParentID, m["prepare[0]"].SpanID)
	}
	if m["quote_fare"].ParentID != m["prepare[1]"].SpanID {
		t.Fatalf("quote_fare parent = %q, want %q", m["quote_fare"].ParentID, m["prepare[1]"].SpanID)
	}
}

func TestRestaurantCallCarriesTraceHeaders(t *testing.T) {
	svc, tr, got := setup()
	_ = svc.HandleOrder(context.Background(), http.Header{}, "o-6")
	root := byName(tr.Finished())["handle_order"]
	if (*got).Get(dispatch.HeaderTraceID) != root.TraceID || (*got).Get(dispatch.HeaderParentSpan) != root.SpanID {
		t.Fatalf("outgoing headers %v do not point at handle_order %+v", *got, root)
	}
}
